export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || !isActiveMembership(member)) return null;

  return { userId, orgId, role: member.role };
}

/**
 * Refuses work handed to anyone who is not a current member of the org.
 * A former member and a stranger are the same case: the membership is not there.
 */
export async function assertActiveMember(orgId: OrgId, userId: UserId): Promise<Member> {
  const member = await memberRepo.findMembership(orgId, userId);
  if (!member || !isActiveMembership(member)) {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

